#[test]
fn raw_model_task_registers_without_reusing_agent_corpus_semantics() {
    let raw_runtime = BenchmarkRuntimeIdentity::raw_model(BenchmarkHarnessIdentity::new(
        "llama-direct",
        "raw-model-harness-v1",
    ));
    let mut raw = record("model-a", BENCHMARK_TASKS[0], 10);
    raw.identity.task_id = RAW_MODEL_BENCHMARK_TASK_ID.to_owned();
    raw.identity.completion_criteria = RAW_MODEL_COMPLETION_CRITERIA
        .iter()
        .map(|criterion| (*criterion).to_owned())
        .collect();
    raw.identity.runtime_harness_version = raw_runtime.harness.harness_version.clone();
    raw.identity.runtime = Some(raw_runtime.clone());
    assert!(validate_record(&raw).is_ok());

    let mut relabelled_agent_task = record("model-a", BENCHMARK_TASKS[0], 10);
    relabelled_agent_task.identity.runtime = Some(raw_runtime);
    assert!(validate_record(&relabelled_agent_task).is_err());
}

